<script setup lang="ts">import { Head, Link, router } from '@inertiajs/vue3'; import { Plus, Search } from '@lucide/vue'; import { ref } from 'vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; type Recipe={id:string;code:string;name:string;is_active:boolean;versions_count:number;current_version:number|null}; const props=defineProps<{recipes:{data:Recipe[]};filters:{search:string};canManage:boolean}>(); const search=ref(props.filters.search); const apply=()=>router.get('/recipes',{search:search.value},{preserveState:true,replace:true});</script>
<template><Head title="Recetas" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header class="flex justify-between gap-3"><div><h1 class="text-2xl font-semibold">Recetas</h1><p class="text-sm text-muted-foreground">Masas base con fórmulas históricas versionadas.</p></div><Button v-if="canManage" as-child><Link href="/recipes/create"><Plus /> Nueva receta</Link></Button></header><form class="flex max-w-xl gap-2" @submit.prevent="apply"><Input v-model="search" placeholder="Código o nombre" /><Button type="submit" variant="outline"><Search /> Buscar</Button></form><section class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3">Receta</th><th class="px-4 py-3">Versiones</th><th class="px-4 py-3">Vigente hoy</th><th class="px-4 py-3">Estado</th><th></th></tr></thead><tbody class="divide-y"><tr v-for="recipe in recipes.data" :key="recipe.id"><td class="px-4 py-3"><p class="font-medium">{{ recipe.name }}</p><code class="text-xs text-muted-foreground">{{ recipe.code }}</code></td><td class="px-4 py-3">{{ recipe.versions_count }}</td><td class="px-4 py-3">{{ recipe.current_version ? `v${recipe.current_version}` : 'Sin versión vigente' }}</td><td class="px-4 py-3">{{ recipe.is_active?'Activa':'Inactiva' }}</td><td class="px-4 py-3 text-right"><Link :href="`/recipes/${recipe.id}`" class="font-medium text-amber-700 hover:underline">Ver</Link></td></tr></tbody></table><p v-if="recipes.data.length===0" class="p-10 text-center text-sm text-muted-foreground">No hay recetas para mostrar.</p></section></main></template>
